from app.utils.sql_helpers import sql_string,sql_json,clamp_int
async def save_section(db,s):
 if s.gameSectionId:return await db.execute_sql(f"UPDATE bc.game_section SET slug={sql_string(s.slug,100)},title={sql_string(s.title,180)},description={sql_string(s.description,900)},order_index={s.orderIndex},is_active={1 if s.isActive else 0} WHERE game_section_id={s.gameSectionId};SELECT {s.gameSectionId} gameSectionId;")
 return await db.execute_sql(f"DECLARE @id INT=(SELECT COALESCE(MAX(game_section_id),0)+1 FROM bc.game_section);INSERT INTO bc.game_section VALUES(@id,{sql_string(s.slug,100)},{sql_string(s.title,180)},{sql_string(s.description,900)},{s.orderIndex},{1 if s.isActive else 0});SELECT @id gameSectionId;")
async def deactivate_section(db,id): return await db.execute_sql(f"UPDATE bc.game_section SET is_active=0 WHERE game_section_id={id};UPDATE bc.game_phase SET is_active=0 WHERE game_section_id={id};")
async def save_phase(db,p):
 q='NULL' if p.questionCount is None else str(p.questionCount)
 if p.gamePhaseId:return await db.execute_sql(f"UPDATE bc.game_phase SET game_section_id={p.gameSectionId},game_engine_id={p.gameEngineId},slug={sql_string(p.slug,100)},title={sql_string(p.title,180)},description={sql_string(p.description,900)},order_index={p.orderIndex},question_count={q},pass_score={p.passScore},max_score={p.maxScore},config_json={sql_string(p.configJson,200000)},is_active={1 if p.isActive else 0} WHERE game_phase_id={p.gamePhaseId};SELECT {p.gamePhaseId} gamePhaseId;")
 return await db.execute_sql(f"DECLARE @id INT=(SELECT COALESCE(MAX(game_phase_id),0)+1 FROM bc.game_phase);INSERT INTO bc.game_phase(game_phase_id,public_phase_id,game_section_id,game_engine_id,slug,title,description,order_index,question_count,pass_score,max_score,config_json,is_active,created_at) VALUES(@id,NEWID(),{p.gameSectionId},{p.gameEngineId},{sql_string(p.slug,100)},{sql_string(p.title,180)},{sql_string(p.description,900)},{p.orderIndex},{q},{p.passScore},{p.maxScore},{sql_string(p.configJson,200000)},{1 if p.isActive else 0},SYSUTCDATETIME());SELECT @id gamePhaseId;")
async def save_question(db,q):
 sets=f"prompt={sql_string(q.prompt)},simple_explanation={sql_string(q.simpleExplanation)},correct_answer={sql_string(q.correctAnswer,400)},options_json={sql_json(q.options)},metadata_json={sql_json(q.metadata)},difficulty={q.difficulty},tags={sql_string(q.tags,500)},updated_at=SYSUTCDATETIME()"
 if q.questionId:return await db.execute_sql(f"UPDATE bc.question_bank SET {sets} WHERE question_id={q.questionId};SELECT {q.questionId} questionId;")
 return await db.execute_sql(f"DECLARE @id BIGINT=(SELECT COALESCE(MAX(question_id),0)+1 FROM bc.question_bank);INSERT INTO bc.question_bank(question_id,public_question_id,game_section_id,game_engine_id,difficulty,prompt,simple_explanation,correct_answer,options_json,metadata_json,tags,is_active,created_at,updated_at) VALUES(@id,NEWID(),{q.gameSectionId},{q.gameEngineId},{q.difficulty},{sql_string(q.prompt)},{sql_string(q.simpleExplanation)},{sql_string(q.correctAnswer,400)},{sql_json(q.options)},{sql_json(q.metadata)},{sql_string(q.tags,500)},1,SYSUTCDATETIME(),SYSUTCDATETIME());SELECT @id questionId;")
async def link(db,pid,b): return await db.execute_sql(f"DECLARE @id BIGINT=(SELECT COALESCE(MAX(phase_question_id),0)+1 FROM bc.phase_question);INSERT INTO bc.phase_question VALUES(@id,{pid},{b.questionId},{b.orderIndex},1.0,0);SELECT @id phaseQuestionId;")
async def unlink(db,id): return await db.execute_sql(f"DELETE FROM bc.phase_question WHERE phase_question_id={id};")
async def reusable(db,s,e,p): return await db.execute_sql(f"SELECT TOP 100 qb.question_id questionId,qb.prompt,qb.difficulty FROM bc.question_bank qb WHERE qb.game_section_id={s} AND qb.game_engine_id={e} AND qb.is_active=1 AND NOT EXISTS(SELECT 1 FROM bc.phase_question pq WHERE pq.question_id=qb.question_id AND pq.game_phase_id={p}) ORDER BY qb.updated_at DESC;")
async def move(db,table,id_col,id,direction,parent_clause=''):
 rows=await db.execute_sql(f"SELECT {id_col} id,order_index ord FROM {table} {parent_clause} ORDER BY order_index,{id_col};");i=next((n for n,x in enumerate(rows) if int(x['id'])==id),-1);j=i+direction
 if i<0 or j<0 or j>=len(rows):return {'moved':False}
 a,b=rows[i],rows[j];await db.execute_sql(f"UPDATE {table} SET order_index=CASE WHEN {id_col}={a['id']} THEN {b['ord']} WHEN {id_col}={b['id']} THEN {a['ord']} ELSE order_index END WHERE {id_col} IN({a['id']},{b['id']});");return {'moved':True}
